# ensure statistics table exists at startup
def ensure_statistics_table():
    conn, cursor = get_db()
    cursor.execute("""
    CREATE TABLE IF NOT EXISTS statistics (
        username TEXT PRIMARY KEY,
        wins INTEGER DEFAULT 0,
        losses INTEGER DEFAULT 0
    )
    """)
    conn.commit()
    conn.close()

