    def save_user(self):
        username = self.lineEdit.text()
        password = self.lineEdit_2.text()
        confirm = self.lineEdit_5.text()

        if username == "" or password == "" or confirm == "":
            self.show_msg("All fields are required.")
            return

        if password != confirm:
            self.show_msg("Passwords do not match.")
            return

        conn, cursor = get_db()

        try:
            cursor.execute("INSERT INTO users (username, password) VALUES (?, ?)",
                           (username, password))
            conn.commit()
            self.show_msg("Account created successfully!")
            MainWindow7.hide()
            MainWindow2.show()

        except sqlite3.IntegrityError:
            self.show_msg("Username already exists.")

        finally:
            conn.close()
    def back(self):
        MainWindow7.hide()
        MainWindow2.show()
    
    def show_msg(self, text):
        msg = QtWidgets.QMessageBox()
        msg.setWindowTitle("Message")
        msg.setText(text)
        msg.exec_()
        msg.buttonClicked.connect(self.login)

